CREATE OR REPLACE FUNCTION public.aka_agent_authenticate_control_session(p_token_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_session public.auto_control_sessions%ROWTYPE;
  v_staff public.org_staff%ROWTYPE;
  v_organization public.org_organization%ROWTYPE;
  v_zalo_package public.org_organization_product%ROWTYPE;
  v_sms_package public.org_organization_product%ROWTYPE;
  v_zalo_capabilities record;
  v_zalo_qr_enabled boolean := false;
  v_zalo_web_enabled boolean := false;
  v_zalo_server_enabled boolean := false;
  v_sms_enabled boolean := false;
  v_now timestamptz := now();
  v_vietnam_day_start timestamptz := (
    date_trunc('day', now() AT TIME ZONE 'Asia/Ho_Chi_Minh')
      AT TIME ZONE 'Asia/Ho_Chi_Minh'
  );
BEGIN
  SELECT session.* INTO v_session
  FROM public.auto_control_sessions AS session
  WHERE session.token_hash = p_token_hash
    AND session.revoked_at IS NULL
    AND session.expires_at > v_now
  LIMIT 1;
  IF v_session.id IS NULL THEN RETURN jsonb_build_object('status', 'invalid_session'); END IF;

  SELECT staff.* INTO v_staff
  FROM public.org_staff AS staff
  WHERE staff.id = v_session.staff_id
  LIMIT 1;
  IF v_staff.id IS NULL
    OR v_staff.is_active IS DISTINCT FROM true
    OR v_staff.organization_id IS DISTINCT FROM v_session.organization_id
  THEN
    UPDATE public.auto_control_sessions SET revoked_at = v_now
    WHERE id = v_session.id AND revoked_at IS NULL;
    RETURN jsonb_build_object('status', 'invalid_staff');
  END IF;

  SELECT organization.* INTO v_organization
  FROM public.org_organization AS organization
  WHERE organization.id = v_staff.organization_id
  LIMIT 1;
  IF v_organization.id IS NULL THEN
    UPDATE public.auto_control_sessions SET revoked_at = v_now
    WHERE id = v_session.id AND revoked_at IS NULL;
    RETURN jsonb_build_object('status', 'invalid_organization');
  END IF;

  -- Reuse Desktop's live staff/org expiry rule, before product entitlement checks.
  -- Keep the existing failure status so older Control API clients still revoke safely.
  IF NOT public.aka_agent_staff_time_allowed(v_staff.id) THEN
    UPDATE public.auto_control_sessions SET revoked_at = v_now
    WHERE id = v_session.id AND revoked_at IS NULL;
    RETURN jsonb_build_object('status', 'invalid_staff');
  END IF;

  SELECT * INTO v_zalo_capabilities
  FROM public.resolve_organization_zalo_account_capabilities(v_staff.organization_id);
  IF v_zalo_capabilities.entitlement_id IS NOT NULL THEN
    SELECT entitlement.* INTO v_zalo_package
    FROM public.org_organization_product AS entitlement
    WHERE entitlement.id = v_zalo_capabilities.entitlement_id;
  END IF;

  SELECT entitlement.* INTO v_sms_package
  FROM public.org_organization_product AS entitlement
  WHERE entitlement.organization_id = v_staff.organization_id
    AND entitlement.is_deleted = false
    AND entitlement.product_id = 17
    AND entitlement.expiration_date >= v_vietnam_day_start
  ORDER BY entitlement.created_at DESC NULLS LAST, entitlement.id DESC
  LIMIT 1;

  v_zalo_qr_enabled := COALESCE(v_zalo_capabilities.qr_enabled, false);
  v_zalo_web_enabled := COALESCE(v_zalo_capabilities.web_enabled, false);
  v_zalo_server_enabled := v_zalo_qr_enabled
    AND COALESCE(v_zalo_capabilities.server_enabled, false);
  v_sms_enabled := v_sms_package.id IS NOT NULL;

  IF NOT v_zalo_server_enabled AND NOT v_sms_enabled THEN
    UPDATE public.auto_control_sessions SET revoked_at = v_now
    WHERE id = v_session.id AND revoked_at IS NULL;
    RETURN jsonb_build_object('status', 'capability_unavailable');
  END IF;
  IF v_session.last_seen_at <= v_now - interval '5 minutes' THEN
    UPDATE public.auto_control_sessions SET last_seen_at = v_now
    WHERE id = v_session.id AND revoked_at IS NULL;
  END IF;

  RETURN jsonb_build_object(
    'status', 'authenticated',
    'session', jsonb_build_object(
      'id', v_session.id, 'staff_id', v_session.staff_id,
      'organization_id', v_session.organization_id,
      'client_type', v_session.client_type, 'user_agent', v_session.user_agent,
      'created_at', v_session.created_at, 'last_seen_at', v_session.last_seen_at,
      'expires_at', v_session.expires_at, 'revoked_at', v_session.revoked_at
    ),
    'staff', jsonb_build_object(
      'id', v_staff.id, 'organization_id', v_staff.organization_id,
      'name', v_staff.name, 'username', v_staff.username,
      'phone', v_staff.phone, 'email', v_staff.email,
      'is_active', v_staff.is_active, 'is_zalo_server', v_zalo_server_enabled
    ),
    'organization', jsonb_build_object('id', v_organization.id, 'name', v_organization.name),
    'capabilities', jsonb_build_object(
      'zalo_qr', v_zalo_qr_enabled,
      'zalo_web', v_zalo_web_enabled,
      'zalo_server', v_zalo_server_enabled,
      'sms', v_sms_enabled
    ),
    'zalo_account_capabilities', jsonb_build_object(
      'qr', v_zalo_qr_enabled,
      'web', v_zalo_web_enabled,
      'server', v_zalo_server_enabled,
      'revision', v_zalo_capabilities.capability_revision
    ),
    'zalo_package', CASE WHEN v_zalo_package.id IS NULL THEN NULL ELSE jsonb_build_object(
      'id', v_zalo_package.id,
      'product_id', v_zalo_package.product_id,
      'product_package_id', v_zalo_package.product_package_id,
      'product_name', v_zalo_package.product_name,
      'package_name', v_zalo_package.package_name,
      'max_accounts', v_zalo_capabilities.max_accounts,
      'max_staff', v_zalo_package.max_staff,
      'max_sends_per_day', v_zalo_capabilities.max_sends_per_day,
      'expiration_date', v_zalo_package.expiration_date,
      'created_at', v_zalo_package.created_at,
      'capability_revision', v_zalo_capabilities.capability_revision
    ) END,
    'sms_package', CASE WHEN v_sms_package.id IS NULL THEN NULL ELSE jsonb_build_object(
      'id', v_sms_package.id,
      'product_id', v_sms_package.product_id,
      'product_package_id', v_sms_package.product_package_id,
      'product_name', v_sms_package.product_name,
      'package_name', v_sms_package.package_name,
      'max_accounts', v_sms_package.max_accounts,
      'max_staff', v_sms_package.max_staff,
      'max_sends_per_day', v_sms_package.max_sends_per_day,
      'expiration_date', v_sms_package.expiration_date,
      'created_at', v_sms_package.created_at
    ) END
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_control_web_device_claim(p_staff_id bigint, p_organization_id bigint, p_session_id uuid, p_device_id uuid, p_token_hash text, p_client_type text, p_user_agent text, p_expires_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
 SET lock_timeout TO '3s'
 SET statement_timeout TO '8s'
AS $function$
DECLARE
  v_policy public.auto_control_web_device_policy%ROWTYPE;
  v_session public.auto_control_sessions%ROWTYPE;
  v_device uuid;
  v_used integer;
  v_existing boolean;
  v_now timestamptz := clock_timestamp();
BEGIN
  -- Shared policy lock permits unrelated staff to enter concurrently and serializes
  -- an effective setting change with admission. Staff lock covers count + write.
  SELECT * INTO STRICT v_policy FROM public.auto_control_web_device_policy WHERE singleton FOR SHARE;
  PERFORM 1 FROM public.org_staff WHERE id=p_staff_id AND organization_id=p_organization_id
    AND is_active IS TRUE AND is_policy_accepted IS TRUE FOR UPDATE;
  IF NOT FOUND OR NOT public.aka_agent_staff_time_allowed(p_staff_id) THEN
    RETURN jsonb_build_object('status','invalid_staff');
  END IF;
  v_now := clock_timestamp();
  IF p_session_id IS NOT NULL THEN
    SELECT * INTO v_session FROM public.auto_control_sessions
    WHERE id=p_session_id AND staff_id=p_staff_id AND organization_id=p_organization_id
      AND revoked_at IS NULL AND expires_at>v_now AND client_type IN ('web','pwa') FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('status','invalid_session'); END IF;
  ELSIF p_client_type IS NULL OR p_client_type NOT IN ('web','pwa')
    OR p_token_hash IS NULL OR p_token_hash !~ '^[0-9a-f]{64}$'
    OR p_expires_at IS NULL OR p_expires_at<=v_now THEN
    RAISE EXCEPTION 'invalid web session input';
  END IF;
  -- A second tab with no device cookie recovers the same committed identity.
  v_device := coalesce(v_session.web_device_id,p_device_id,gen_random_uuid());
  SELECT count(DISTINCT web_device_id),coalesce(bool_or(web_device_id=v_device),false)
    INTO v_used,v_existing FROM public.auto_control_sessions
  WHERE staff_id=p_staff_id AND organization_id=p_organization_id
    AND client_type IN ('web','pwa') AND revoked_at IS NULL AND expires_at>v_now
    AND web_device_revision=v_policy.revision;
  IF NOT v_existing AND v_used>=v_policy.max_devices THEN
    -- Commit the rejected restoration's revocation before the API returns 409.
    -- Existing pages on other devices remain valid until their own next entry.
    IF p_session_id IS NOT NULL THEN
      UPDATE public.auto_control_sessions SET revoked_at=v_now
      WHERE staff_id=p_staff_id AND organization_id=p_organization_id AND client_type IN ('web','pwa')
        AND revoked_at IS NULL AND (id=p_session_id OR web_device_id=v_device);
    END IF;
    RETURN jsonb_build_object('status','limit_reached','limit',v_policy.max_devices,'used',v_used);
  END IF;
  IF p_session_id IS NULL THEN
    UPDATE public.auto_control_sessions SET revoked_at=v_now
    WHERE staff_id=p_staff_id AND organization_id=p_organization_id AND web_device_id=v_device
      AND client_type IN ('web','pwa') AND revoked_at IS NULL;
    INSERT INTO public.auto_control_sessions(staff_id,organization_id,token_hash,client_type,user_agent,
      expires_at,web_device_id,web_device_revision,web_device_registered_at)
    VALUES(p_staff_id,p_organization_id,p_token_hash,p_client_type,left(p_user_agent,1000),
      p_expires_at,v_device,v_policy.revision,v_now) RETURNING * INTO v_session;
  ELSE
    UPDATE public.auto_control_sessions SET web_device_id=v_device,web_device_revision=v_policy.revision,
      web_device_registered_at=CASE WHEN web_device_revision=v_policy.revision THEN web_device_registered_at ELSE v_now END
    WHERE id=p_session_id RETURNING * INTO v_session;
  END IF;
  RETURN jsonb_build_object('status','admitted','deviceId',v_device,
    'quota',jsonb_build_object('limit',v_policy.max_devices,'used',v_used+CASE WHEN v_existing THEN 0 ELSE 1 END),
    'session',to_jsonb(v_session)-'token_hash'-'web_device_id'-'web_device_revision'-'web_device_registered_at');
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_control_web_device_policy_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_limit integer;
BEGIN
  IF (TG_OP<>'INSERT' AND OLD.key='web.auth.max_devices_per_staff')
    OR (TG_OP<>'DELETE' AND NEW.key='web.auth.max_devices_per_staff') THEN
    SELECT public.aka_agent_control_web_device_limit(value,is_active,is_secret) INTO v_limit
    FROM public.auto_system_settings WHERE key='web.auth.max_devices_per_staff';
    UPDATE public.auto_control_web_device_policy SET max_devices=coalesce(v_limit,3),revision=gen_random_uuid()
    WHERE singleton AND max_devices IS DISTINCT FROM coalesce(v_limit,3);
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_control_web_device_revoke(p_staff_id bigint, p_organization_id bigint, p_session_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
 SET lock_timeout TO '3s'
 SET statement_timeout TO '8s'
AS $function$
DECLARE v_session public.auto_control_sessions%ROWTYPE;
BEGIN
  PERFORM 1 FROM public.org_staff WHERE id=p_staff_id AND organization_id=p_organization_id FOR UPDATE;
  IF NOT FOUND THEN RETURN false; END IF;
  SELECT * INTO v_session FROM public.auto_control_sessions WHERE id=p_session_id
    AND staff_id=p_staff_id AND organization_id=p_organization_id AND revoked_at IS NULL;
  IF NOT FOUND THEN RETURN false; END IF;
  UPDATE public.auto_control_sessions SET revoked_at=clock_timestamp()
  WHERE staff_id=p_staff_id AND organization_id=p_organization_id AND revoked_at IS NULL
    AND (id=p_session_id OR (v_session.client_type IN ('web','pwa') AND client_type IN ('web','pwa')
      AND web_device_id=v_session.web_device_id));
  RETURN true;
END;
$function$
